def transform(g):
    H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]
    out=[row[:] for row in g]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; comp=[]
                while stack:
                    r,c=stack.pop(); comp.append((r,c))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<H and 0<=nc<W and g[nr][nc] and not seen[nr][nc]:
                            seen[nr][nc]=True; stack.append((nr,nc))
                cells={}
                for r,c in comp: cells.setdefault(g[r][c],[]).append((r,c))
                def bbox(c):
                    rs=[r for r,_ in cells[c]]; cs=[c for _,c in cells[c]]
                    return (max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)
                L=sorted(cells,key=bbox,reverse=True)
                k=len(L)
                mapping={L[t]:L[k-1-t] for t in range(k)}
                for r,c in comp: out[r][c]=mapping[g[r][c]]
    return out
